function vhead(eyebrow,title,lang){
 return '<div class="vhead"><div><p class="eyebrow">'+eyebrow+'</p><h2>'+title+'</h2></div><button class="link" type="button" data-jump="formats"><span aria-hidden="true">↑</span> '+UI[lang].allFormats+'</button></div>';
}
function brief(meta,facts){
 var m=meta.map(function(x){return x[0]==='_'?'<p class="disc">'+x[1]+'</p>':'<span class="chip"><b>'+x[0]+'</b><span>'+x[1]+'</span></span>'}).join('');
 var f=facts.map(function(x){return '<div><h4>'+x[0]+'</h4><p>'+x[1]+'</p></div>'}).join('');
 return '<div class="specs"><div class="chips rv">'+m+'</div><div class="quads rv" style="--d:80ms">'+f+'</div></div>';
}
/* unidad anotada: l = etiqueta/nota izq, c = copy, r = nota der */
