function renderLP(){
 var body=
  U('<p class="eb">Daily support for better focus</p><p class="hh big"><span class="ul">Give your brain the support it needs</span> to stay focused, keep going, and finish what you start.</p><p>Clarity is a daily nootropic supplement designed to support sustained focus, clearer thinking, and more consistent follow-through.</p>',{label:"1. Hero",nr:"Leads with the main outcome—better, more consistent focus—and makes the offer and price visible immediately for warmer visitors already considering a solution."})+
  U('<div class="offer"><span class="pp"><s>$129</s> $59</span><b style="font:700 .66rem/1.3 var(--sans);letter-spacing:.14em">1 MONTH SUPPLY · <span style="color:var(--rosa-prof)">SAVE 54%</span></b><small>$2.36/day · Ships every 25 days · Then $79/month</small></div><span class="fake-btn">Start with Clarity — 50% Off Your First Month</span><p class="fine">Choose with or without caffeine.</p>',{label:"Offer"})+
  U('<p class="hh">What could change when your focus feels <span class="ul">better supported</span>?</p><p>Clarity is designed to support sustained attention and clearer thinking, so you can spend more of your mental energy moving forward instead of constantly finding your focus again.</p><div class="kv"><div><b>STAY WITH ONE TASK LONGER.</b><span>Give your attention more consistent support while you work.</span></div><div><b>THINK MORE CLEARLY.</b><span>Support mental clarity when the work in front of you demands it.</span></div><div><b>BUILD STEADIER MOMENTUM.</b><span>Stay engaged long enough to follow through on what you started.</span></div></div>',{label:"2. Benefits",nr:"Uses familiar focus problems to help readers recognize whether Clarity fits their needs."})+
  U('<p class="hh">How Clarity supports your focus <span class="ul">over time</span></p><div class="tline"><div><b>WEEK 1</b><p>Support for sharper focus and steadier mental energy</p><small>CDP Choline and B6 support neurotransmitters involved in attention, focus, and mental energy.</small></div><div><b>MONTH 1</b><p>More consistent focus when you need to follow through</p><small>Citicoline, B6, and Panax Ginseng support mental clarity and resilience to everyday stressors.</small></div><div><b>MONTH 3</b><p>Ongoing support for mental agility</p><small>Lion’s Mane, 7,8-DHF, and B6 support neuroplasticity and cognitive function.</small></div><div><b>MONTH 6</b><p>Long-term support for cognitive resilience</p><small>Lion’s Mane and 7,8-DHF support pathways connected to neurogenesis, memory, and cognitive health.</small></div></div>',{label:"3. How it works",nr:"Shows how different ingredients support focus at different stages, without making the science feel overly technical."})+
  U('<p class="hh">Join hundreds of thousands of customers already supporting their focus with Thesis</p>',{label:"4. Social proof"})+
  U('<p class="eb">Is Clarity right for you?</p><p class="hh">Clarity may be right for you if…</p><ul class="checks"><li>You know what you need to do, but staying focused long enough to finish it is the hard part.</li><li>You jump from one task to another and end the day with too many things half-done.</li><li>A single interruption can make it difficult to get back into what you were doing.</li><li>Mental fog makes work feel slower or harder than it needs to be.</li><li>You want daily support for focus without depending on another cup of coffee.</li></ul><p class="fine">Clarity does not replace sleep, healthy habits, or the work itself. It is designed to support the cognitive processes involved in staying focused and mentally engaged.</p><span class="fake-btn">Get Clarity Now</span>',{label:"5. Is it for you?"})+
  U('<p class="eb">Choose your Clarity supply</p><p>Choose how you want to start. Every option includes free shipping and the same Clarity formula—just with a different supply and subscription price.</p><div class="price"><div class="plan"><b>1 MONTH SUPPLY</b><span class="pp"><s>$129</s>$59</span><span class="save">Save 54%</span><small>$2.36/dose · Ships every 25 days<br>Then $79/month</small><span class="pc">Start With 1 Month</span></div><div class="plan"><b>2 MONTH SUPPLY</b><span class="pp"><s>$258</s>$108</span><span class="save">Save 58%</span><small>$2.16/dose · Ships every 50 days<br>Then $74/month</small><span class="pc">Start With 2 Months</span></div><div class="plan best"><span class="badge">BEST VALUE</span><b>3 MONTH SUPPLY</b><span class="pp"><s>$387</s>$147</span><span class="save">Save 62%</span><small>$1.96/dose · Ships every 75 days<br>Then $69/month<br><b style="color:var(--tinta)">Get the Lowest Monthly Price</b></small><span class="pc">Start With 3 Months</span></div></div>',{label:"6. Pricing",nr:"Uses flexible plan options to make the purchase easier."})+
  U('<p class="eb">Try Clarity for 30 days</p><p class="hh">Feel the difference in your focus—<span class="ul">or get your money back.</span></p><p>Give Clarity 30 days to become part of your routine.</p><p>If you don’t feel at least a 50% improvement in the cognitive focus area you’re targeting within 30 days, Thesis will refund your purchase.</p><p>No guessing whether it was worth trying. You have 30 days to decide for yourself.</p><span class="fake-btn">Try Clarity Now</span>',{label:"7. Guarantee",nr:"Gives readers an extra reason to try Clarity by making the decision feel less risky."});
 return vhead("Landing Page","From interest in focus support <em>to a confident purchase.</em>","en")+
  brief([["Project","Thesis · Clarity"],["Industry","DTC Ecommerce / Nootropics"],["Work","Spec Project"],["_","Independent spec work. Not commissioned by or affiliated with Thesis."]],
   [["Project overview","Thesis is a DTC nootropic brand offering targeted formulas for focus, motivation, stress support, and memory. For this spec project, I rewrote the homepage and Clarity product landing page for two different moments in the customer journey."],["The challenge","Turn existing interest in focus support into enough confidence to choose Clarity and make a purchase."],["Audience & awareness","Solution-to-product-aware. Prospects already looking for focus support who need enough proof and reassurance to choose Clarity."],["Approach","Lead with the outcome and offer, then build confidence through benefits, proof, pricing, and risk reversal."]])+
  '<div class="ann lp">'+body+'</div>';
}

/* ───────────── EN · HOMEPAGE (Thesis) ───────────── */
function renderHome(){
 var map=[["When it’s hard to stay focused on the task in front of you.","CLARITY","Helps you stay focused longer, think more clearly, and give your attention to what matters."],["You know what you need to do, but can’t find the motivation to begin.","MOTIVATION","Helps you find the mental energy to get started, build momentum, and follow through."],["When pressure takes over and it’s hard to stay calm.","STRESS RESET","Helps you feel calmer under pressure, manage everyday stress, and respond with a clearer mind."],["When you want to keep your memory and mind sharp over time.","NEUROPROTECTION","Helps support memory, learning, and long-term brain health, so your mind can stay active and engaged."]].map(function(m){return '<div class="maprow"><span class="p">'+m[0]+'</span><span class="x">→</span><span><b>'+m[1]+'</b>'+m[2]+'</span></div>'}).join('');
 var body=
  U('<p class="hh big">Need more focus? More drive? <span class="ul">A calmer mind? Sharper memory?</span></p><p>Whatever your mind needs most, this nootropic supplement helps you support it.</p>',{label:"1. Hero",nr:"Leads with the outcomes people already want before introducing nootropics or ingredients."})+
  U('<p>Take the quiz to discover which one best fits yours.</p><span class="fake-btn">Find Your Formula</span>',{nr:"Uses the quiz as a lower-friction next step for visitors who aren’t ready to choose a formula yet."})+
  U('<p class="hh">What keeps getting between you and <span class="ul">your best work</span>?</p><p>You know what you want to accomplish. But staying focused, finding the drive to begin, managing pressure, or retaining what you learn can make progress feel harder.</p>',{label:"2. Agitation"})+
  U('<p class="eb">Your brain works differently from everyone else’s, and there’s a Thesis to help you.</p><p class="hh">You can support your brain <span class="ul">where you need it most</span></p><p>Each Thesis formula is designed to support a different cognitive goal. Explore the options below, or take the quiz if you are not sure where to begin.</p><div>'+map+'</div><span class="fake-btn">Do the quiz</span>',{label:"3. Formulas",nr:"Connects each formula to a specific problem, helping visitors quickly identify which option feels most relevant to them."})+
  U('<p class="eb">How Thesis can help you</p><p class="hh">Different cognitive goals call for different support.</p><p>Your ability to focus, feel motivated, stay calm under pressure, and remember what you learn depends on different processes in your brain.</p><p>Thesis combines specific active ingredients in precise doses to support the processes connected to the goal you choose.</p><div class="kv"><div><b>TARGETED TO YOUR GOAL</b><span>Thesis combines specific active ingredients in precise doses to support the area where your mind needs it most.</span></div><div><b>FORMULATED TO WORK TOGETHER</b><span>The ingredients are selected as a formula, rather than added as a collection of trending compounds.</span></div><div><b>PROGRESS YOU CAN EVALUATE</b><span>Use your formula consistently and pay attention to the area you chose to support.</span></div></div>',{label:"4. How it works"})+
  U('<p class="hh">Support your mind with ingredients <span class="ul">you can trust.</span></p><p>Thesis uses clinically researched, plant-derived active compounds and clearly lists each ingredient and dosage.</p><p>Every ingredient in every batch is independently tested for purity and potency, so you know what is inside your formula—and how much.</p>',{label:"5. Features"})+
  U('<div class="trio"><div><span class="num">700+</span><small>Studies analyzed when developing formulas</small></div><div><span class="num">30+</span><small>Beta tests conducted with real customers</small></div><div><span class="num">7.3M</span><small>Data points collected across customer trials</small></div></div><div class="kv"><div><b>ACTIVE INGREDIENT TESTING</b><span>Confirms that each formula contains the amounts listed on the label.</span></div><div><b>MICROBIAL TESTING</b><span>Screens formulas for microorganisms, including bacteria and fungi.</span></div><div><b>HEAVY METAL TESTING</b><span>Checks every batch for harmful heavy metals, including lead, arsenic, cadmium, and mercury.</span></div><div><b>PESTICIDE TESTING</b><span>Tests raw materials for pesticide residues, including trace amounts.</span></div></div>',{label:"6. Proof",nr:"Introduces research and testing after the benefits are clear, so the science supports the promise instead of overwhelming the reader."})+
  U('<p class="hh">What customers noticed after starting Thesis</p><p>More than 10,000 verified five-star reviews show how Thesis formulas have become part of customers’ everyday routines.</p><div class="trio"><div><span class="num">83%</span><small>of customers in a Clarity study reported feeling more focused after 30 days.</small></div><div><span class="num">78%</span><small>reduction in reported brain fog among customers in the same Clarity study.</small></div><div><span class="num">83%</span><small>of customers in a Stress Reset study reported reduced stress after 30 days.</small></div></div><div class="quotes"><q>It has completely changed my focus and motivation.</q><q>The boost I need for my productivity.</q><q>I start every day off with Thesis.</q></div><span class="fake-btn">Find Your Thesis</span><p class="fine">Results are based on open-label consumer perception studies and were self-reported. Individual results may vary.</p>',{label:"7. Testimonials"})+
  U('<p class="eb">Questions worth asking</p><div class="faq"><div>Do I really need a supplement for this?</div><div>Is Thesis safe?</div><div>Will I have to rely on it to function?</div><div>How soon could I notice a difference?</div><div>How much does Thesis cost?</div><div>What if it does not work for me?</div></div>',{label:"8. FAQ",nr:"Addresses the questions most likely to delay a purchase."})+
  U('<p class="eb">Start with what your mind needs most</p><p class="hh">You do not have to guess your way toward better support.</p><p>Take the three-minute quiz to discover the Thesis formula designed around the cognitive goal you want to prioritize.</p><span class="fake-btn">Find My Formula</span><p class="fine">30-day money-back guarantee · Free shipping · Cancel anytime</p>',{label:"9. Final CTA"});
 return vhead("Homepage","Helping visitors find <em>the formula their mind needs.</em>","en")+
  brief([["Project","Thesis"],["Industry","DTC Ecommerce / Nootropics"],["Work","Spec Project"],["_","Independent spec work. Not commissioned by or affiliated with Thesis."]],
   [["Project overview","Thesis is a DTC nootropic brand offering targeted formulas for focus, motivation, stress support, and memory. For this spec project, I rewrote the homepage and Clarity product landing page for two different moments in the customer journey."],["The challenge","Help visitors understand which type of cognitive support they need without overwhelming them with a technical product category."],["Audience & awareness","Problem-aware visitors who know what they’re struggling with but not yet which formula could help."],["Approach","Lead with desired outcomes, make each formula easier to understand, and introduce science and proof after the benefits are clear."]])+
  '<div class="ann lp">'+body+'</div>';
}

