function renderVSL(){
 var n=0; function H(t){n++;return '<h5><span class="no">'+n+'</span>'+t+'</h5>'}
 var body=
  U('<p class="stitle">VSL script · Tawkify</p>')+
  U(H('Hook · Affirmation sentence')+'<p><mark class="hl">You can be dating more than ever and still feel no closer to finding your person.</mark></p>',{nr:"Uses contradiction to grab attention and create immediate tension."})+
  U(H('Agitate the problem')+'<p>You match with someone. You exchange a few messages. Maybe you’re carrying on three or four half-conversations at the same time.</p><p>Then one disappears. Another never makes it to a date. And someone else turns out to be looking for something completely different.</p><p>You’re putting in the effort. You’re just not necessarily getting closer to the relationship you actually want.</p>')+
  U(H('Increase the emotional cost')+'<p>And after a while, it’s not just frustrating. <mark class="hl">It’s exhausting.</mark></p><p>You start every new conversation hoping this one might be different, only to find yourself back in the same cycle a few days later.</p><p>And even when you meet someone who seems right at first, that doesn’t mean you share the same values, intentions, or vision for the future.</p>',{nl:"Builds emotional recognition before introducing the solution."})+
  U(H('Solution + How it works')+'<p><mark class="hl">There is a more refreshing way to date.</mark></p><p>Tawkify is a personalized matchmaking service for people who are serious about finding a meaningful relationship.</p>',{nr:"Positions matchmaking as a different way to date—not an attack on dating apps."})+
  U('<p>It starts with a one-on-one conversation with a professional matchmaker who gets to know your lifestyle, your dating history, your relationship goals, and what you’re really looking for in a partner.</p><div class="triple"><p><mark class="hl">They search for people who fit what matters to you.</mark></p><p><mark class="hl" style="--d:450ms">They screen potential matches before you meet.</mark></p><p><mark class="hl" style="--d:650ms">And your feedback helps them refine the search toward the right match.</mark></p></div>',{nl:"Uses the rule of three to make the core process easier to remember."})+
  U(H('Transformation')+'<p>You can stop endlessly swiping through profiles and burning yourself out trying to keep conversations alive.</p><p>You get to keep living your life, knowing someone is looking for the right person for you. And when there’s someone worth meeting, you can focus on what actually matters: the connection.</p>')+
  U(H('Authority')+'<p>Tawkify is the <mark class="hl">#1 matchmaking service in America</mark>, with access to a network of more than 3 million relationship-ready singles.</p><p>Technology helps narrow the search, but your matchmaker will decide who might actually be right for you.</p>')+
  U(H('Social proof')+'<p>For Lyndsey, that shift changed everything.</p><p>She was exhausted by repetitive online dating and half-conversations with strangers. Tawkify let her step back while her matchmaker searched for someone compatible.</p><p>And eventually, she met the man she now calls <mark class="hl">the love of her life.</mark></p>',{nr:"Turns social proof into a short success story the audience can identify with."})+
  U(H('Benefits')+'<p>Because the goal isn’t to meet more people. It’s to spend your time meeting people who have real potential to be right for you.</p>')+
  U(H('Reasons to act now')+'<p><mark class="hl">Do you really want to keep dating the same way and hoping for a different result?</mark></p>',{nl:"Challenges the reader while connecting back to the hook."})+
  U('<p>The first step is simple: schedule a consultation to find out whether Tawkify is the right fit for you.</p><p><mark class="hl">There’s no pressure to move forward unless it feels right.</mark></p>',{nr:"Reduces pressure around the next step."})+
  U(H('Emotional close + CTA')+'<p>You don’t need more matches. You need a real chance to meet someone who could become the love you’ve been looking for.</p><p>Click the button below to schedule your consultation and <mark class="hl">take the first step toward your last first date.</mark></p>',{nl:"Ends on the emotional outcome the audience wants: to find love."});
 return vhead("VSL Script","From dating fatigue <em>to booking a consultation.</em>","en")+
  brief([["Project","Tawkify"],["Industry","Dating / Professional Matchmaking"],["Work","Spec Project"],["Brand website","tawkify.com"],["_","Independent spec work. Not commissioned by or affiliated with Tawkify."]],
   [["Project overview","Tawkify is a personalized matchmaking service for people looking for meaningful relationships. For this spec project, I wrote a VSL designed to move prospects from frustration with modern dating toward considering professional matchmaking and booking a consultation."],["The challenge","Present matchmaking as a more intentional way to date without attacking dating apps or making unrealistic promises."],["Audience & awareness","Problem-aware adults tired of swiping, half-conversations, and dates that go nowhere."],["Approach","I chose a VSL because a premium, high-consideration service needs more space to build trust, explain the value, and reduce friction before asking prospects to book a consultation."],["Research","I reviewed Tawkify’s website and customer testimonials to identify recurring pain points, objections, and Voice of Customer language, then used those insights throughout the script."]])+
  '<div class="ann vs">'+body+'</div>';
}

